export function updatesFromSteam(family: GameFamily): boolean {
  return Boolean(STEAM_APPID[family]);
}

/** Seconds we wait for the unit to come back before we stop claiming anything. */
export const RESTART_WAIT_TRIES = 30;
export const RESTART_WAIT_SLEEP_S = 2;

/**
 * Build the remote script.
 *
 * Design rules, each of which the old one-liner broke:
 *
 *  - No `set -e` and no trailing `; true`. Control flow is explicit, and the exit
 *    status is irrelevant — the MARKERS are the contract, so a truncated or
 *    dropped connection is detectable (no `NXGU:END`) rather than indistinguishable
 *    from success.
 *  - steamcmd's own exit code is not trusted (it is famously unreliable and
 *    frequently non-zero on a perfectly good update). We match its own success
 *    line instead, and report the code alongside.
 *  - "no unit matched" is an outcome we emit, not a branch we swallow.
 *  - The post-restart state is polled and reported verbatim. `active` is the only
 *    thing that will be called success upstream.
 *
 * `family` is constrained to GAME_FAMILIES by the caller AND re-checked here, so
 * nothing unvalidated is interpolated into the shell.
 */
export function updateCommand(family: GameFamily): string {
  if (!GAME_FAMILIES.includes(family)) throw new Error(`not a game family: ${family}`);
  const appId = STEAM_APPID[family];
  const svc = SERVICE_HINT[family];
  // Both are compile-time constants from the tables above — never customer input.

  // Emitted by every branch that must not go on to restart the service.
  const stopHere = [
    `st=$(systemctl is-active "$unit" 2>/dev/null)`,
    `say "SKIPPED_RESTART:1"`,
    `say "STATE:${"$"}{st:-unknown}"`,
    `say "END"`,
    `exit 0`,
  ];

  const steam = appId
    ? [
        `fresh=0`,
        `if command -v steamcmd >/dev/null 2>&1; then`,
        `  out=$(steamcmd +login anonymous +app_update ${appId} validate +quit 2>&1); rc=$?`,
        `  say "STEAM_RC:$rc"`,
        // steamcmd prints "Success! App '<id>' already up to date." when there was
        // nothing to download, and "Success! App '<id>' fully installed." when
        // there was. Both used to match one grep, so the two outcomes were
        // indistinguishable — see the CURRENT/OK split in the header note.
        `  if printf '%s' "$out" | grep -q "Success! App '${appId}' already up to date"; then`,
        `    say "STEAM:CURRENT"`,
        `  elif printf '%s' "$out" | grep -q "Success! App '${appId}'"; then`,
        `    fresh=1; say "STEAM:OK"`,
        `  else`,
        `    say "STEAM:FAIL"`,
        `    printf '%s' "$out" | grep -i 'error' | head -3 | while IFS= read -r l; do say "STEAM_ERR:$l"; done`,
        `  fi`,
        `else`,
        `  say "STEAM:ABSENT"`,
        `fi`,
