        // a restart kicks every connected player off for nothing, and it would
        // make "the service was restarted" the only true half of a false claim.
        // This now also covers the "already up to date" case, which is the COMMON
        // one — it ran every 6 hours and disconnected everybody four times a day.
        `if [ "$fresh" != "1" ]; then`,
        ...stopHere.map((l) => `  ${l}`),
        `fi`,
      ].join("\n")
    : [
        // No update source exists for this family, so there is nothing a restart
        // could apply. Restarting anyway is a pure loss: every connected player
        // is disconnected, four times a day, forever, to change nothing. The
        // rule two paragraphs up applies here MOST, and used not to be applied
        // here at all.
        `say "STEAM:NA"`,
        ...stopHere,
      ].join("\n");

  return [
    `say() { printf 'NXGU:%s\\n' "$1"; }`,
    // 1. Resolve the unit. `systemctl cat` succeeds only for a unit that exists.
    `unit=""`,

